---@class OverSeaManageSettingLeftCell
local OverSeaManageSettingLeftCell = Class('OverSeaManageSettingLeftCell')
local FoodItemCellPath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverSeaManageSettingLeftFoodCell"

function OverSeaManageSettingLeftCell:__init()
    
    self.callBack = nil
end

function OverSeaManageSettingLeftCell:__delete()
    
    self.callBack = nil
    self.foodNodeCell = nil
end

function OverSeaManageSettingLeftCell:Awake()
    self:InitFoodItem()
end

function OverSeaManageSettingLeftCell:InitFoodItem()
    if self.FoodNode then
        self.foodNodeCell = CfUtils.GetLuaScr(self.FoodNode,FoodItemCellPath)
    end
end

function OverSeaManageSettingLeftCell:SetCallBackAndIndex(callBack,index)
    self.index = index
    self.callBack = callBack
    self.foodNodeCell:SetCallBackAndIndex(Bind(self,self.OnCellClick),index)
    self.foodNodeCell:SetIsPopTip(true)
end

function OverSeaManageSettingLeftCell:OnCellClick()
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local serverInfo =component:GetRecipeDoJoById(self.data.refId)
    if serverInfo then
        if self.callBack then
            self.callBack(self.index)
        end
    else
        self.foodNodeCell:SetSelectStatus(false)
        local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.refId)
        if not isNull(foodVo) then
            if isSet(foodVo, "jumpAway") and table.count(foodVo.jumpAway) > 0 then
                local goodsConfMgr = GoodsConfMgr:GetInstance()
                local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                local canJump = goodsConfMgr:CheckIsCanJump(row)
                if canJump then
                    if isSet(foodVo,"jumpParameter") then
                        local type = GoodsUtils.GetIdType(foodVo.jumpParameter[1], Constants.IDArea.Quests)
                        if type == Constants.IDType.QuestRegion then
                            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                            local isUnLock,str  =  ActionUtils.IsUnlockRegionQuest(foodVo.jumpParameter[1])
                            if isUnLock then
                                local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                                goodsConfMgr:ExecuteJump(row, {},nil,nil,{foodVo.jumpParameter[1]})
                            else
                                GameUtils.Toast(str)
                            end
                        else
                            local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                            goodsConfMgr:ExecuteJump(row, {})
                        end
                    else
                        local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                        local recipeVo = CfUtils.GetCfVo(AutoIds.IdSetting3036, "MaidCoffeeMenuMakeVo", self.data.refId)

                        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(recipeVo.fishId)
                        if goodsVo then
                            goodsConfMgr:ExecuteJump(row, goodsVo)
                        else
                            goodsConfMgr:ExecuteJump(row, {})
                        end
                    end
                end
            else
                printError("id %s  不能前往跳转 没有配置openType",foodVo.id)
            end
        end
    end
end

