| M   | -- *rating*       | int  | 评级(D=1,C=2,B=3,A=4,S=5) |]]
---具体信息 从服务器拿 图标从本地
function OverSeaManageSettingLeftCell:RefreshUI(data)
    self.data = data
    self.foodNodeCell:RefreshUI(data)
    self.foodNodeCell:SetGoToGetStatus(true)
end

function OverSeaManageSettingLeftCell:SetIsDouble(tabIndex,slotIndex)
    self.foodNodeCell:SetIsDouble(tabIndex,slotIndex)
end

function OverSeaManageSettingLeftCell:RefreshSelect(curData)
    if curData ~= nil and curData.refId == self.data.refId then
        self.foodNodeCell:SetSelectStatus(true)
    else
        self.foodNodeCell:SetSelectStatus(false)
    end
end

function OverSeaManageSettingLeftCell:DoSelect()
    self.foodNodeCell:SetSelectStatus(false)
end

function OverSeaManageSettingLeftCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverSeaManageSettingLeftCell